<?= view('partials/header', get_defined_vars()) ?>
<section class="page-banner"><div class="container"><p class="eyebrow">Access management</p><h1><?= esc($formTitle) ?></h1><p>Keep account details accurate and upload an optional avatar.</p></div></section>
